document.addEventListener("DOMContentLoaded", () => {
  const app = document.querySelector("[data-proto-app]");
  if (!app) return;
  const viewport = app.querySelector("[data-viewport]"), world = app.querySelector("[data-world]"), itemsLayer = app.querySelector("[data-items]"), linksLayer = app.querySelector("[data-links]");
  const input = document.querySelector("#prototype-board-data");
  const source = JSON.parse(input?.textContent || "{}");
  const key = `taska-canvas-${source.projectId || "empty"}`;
  let saved = null;
  try { saved = JSON.parse(localStorage.getItem(key) || "null"); } catch (_) { localStorage.removeItem(key); }
  let state = mergeState(buildState(source), saved), selected = null, linkStart = null, selectedLink = null, tool = "select", gesture = null;
  state.view ||= {x:80,y:70,scale:.8}; state.links ||= []; state.notes ||= [];
  const colors = ["#6f7b8a","#3276d1","#d05278","#258b78","#d39b32"];
  const get = id => state.items.find(item => item.id === id);
  const esc = value => {const node=document.createElement("span");node.textContent=value;return node.innerHTML;};
  function buildState(data){
    const items=[], statuses=data.statuses||[], tasks=data.tasks||[];
    statuses.forEach((status,index)=>items.push({id:`status-${status.code}`,type:"status",x:100+index*310,y:100,w:280,h:620,title:status.label,color:colors[index%colors.length],status:status.code}));
    tasks.forEach((task,index)=>{const column=Math.max(0,statuses.findIndex(status=>status.code===task.status)), inside=tasks.filter(item=>item.status===task.status).findIndex(item=>item.id===task.id);items.push({id:`task-${task.id}`,sourceId:task.id,type:"task",x:125+column*310,y:180+inside*125,w:230,h:105,title:task.title,color:colors[column%colors.length],status:task.status,sprintId:task.sprintId,storyPoints:task.storyPoints||0,priority:task.priority});});
    (data.sprints||[]).forEach((sprint,index)=>items.push({id:`sprint-${sprint.id}`,sourceId:sprint.id,type:"sprint",x:100+index*340,y:850,w:320,h:190,title:sprint.name,color:"#8b68d0",status:sprint.status}));
    return {title:data.projectName||"Kanban",items,links:[],notes:[],view:{x:80,y:70,scale:.8}};
  }
  function mergeState(fresh, old){
    if(!old)return fresh;
    const oldById=new Map((old.items||[]).map(item=>[item.id,item]));
    fresh.items.forEach(item=>{const prior=oldById.get(item.id);if(prior)Object.assign(item,{x:prior.x,y:prior.y,w:prior.w,h:prior.h,color:prior.color});});
    const freshIds=new Set(fresh.items.map(item=>item.id));
    const local=(old.items||[]).filter(item=>!item.sourceId&&item.type==="note");
    fresh.items.push(...local);
    fresh.links=(old.links||[]).filter(link=>(freshIds.has(link.from)||local.some(item=>item.id===link.from))&&(freshIds.has(link.to)||local.some(item=>item.id===link.to)));
    fresh.view=old.view||fresh.view; return fresh;
  }
  const save=()=>{localStorage.setItem(key,JSON.stringify(state));updateMinimap();};
  const worldPoint=(x,y)=>{const rect=viewport.getBoundingClientRect();return{x:(x-rect.left-state.view.x)/state.view.scale,y:(y-rect.top-state.view.y)/state.view.scale};};
  const applyView=()=>{world.style.transform=`translate(${state.view.x}px,${state.view.y}px) scale(${state.view.scale})`;app.querySelector("[data-zoom-label]").textContent=`${Math.round(state.view.scale*100)}%`;drawLinks();updateMinimap();};
  const label={task:"Задача",status:"Статус",sprint:"Спринт",note:"Заметка"};
  function render(){
    itemsLayer.replaceChildren();
    state.items.forEach(item=>{const node=document.createElement("article");node.className=`proto-item proto-${item.type}${selected===item.id?" selected":""}`;node.dataset.id=item.id;node.style.cssText=`left:${item.x}px;top:${item.y}px;width:${item.w}px;height:${item.h}px;--item-color:${item.color}`;node.innerHTML=`<header><span>${label[item.type]}</span><button type="button" title="Свойства">•••</button></header><div class="proto-item-body"><strong>${esc(item.title)}</strong>${item.type==="task"?`<small>${esc(item.status)} · ${item.storyPoints||0} SP</small>`:""}</div><i class="proto-resize"></i>`;node.addEventListener("pointerdown",itemDown);node.addEventListener("dblclick",()=>openInspector(item.id));node.querySelector("header button").addEventListener("click",e=>{e.stopPropagation();openInspector(item.id);});itemsLayer.append(node);});
    app.querySelector("[data-empty-hint]").hidden=state.items.length>0;drawLinks();updateMinimap();
  }
  function select(id){selected=id;selectedLink=null;render();}
  function itemDown(event){event.stopPropagation();const id=event.currentTarget.dataset.id;if(tool==="connect"){if(!linkStart){linkStart=id;select(id);}else if(linkStart!==id){state.links.push({from:linkStart,to:id});linkStart=null;setTool("select");save();render();}return;}select(id);const p=worldPoint(event.clientX,event.clientY),item=get(id);gesture={kind:event.target.classList.contains("proto-resize")?"resize":"move",id,start:p,origin:{x:item.x,y:item.y,w:item.w,h:item.h}};event.currentTarget.setPointerCapture(event.pointerId);}
  viewport.addEventListener("pointerdown",event=>{if(event.target.closest(".proto-item"))return;selected=null;render();gesture={kind:"pan",start:{x:event.clientX,y:event.clientY},origin:{x:state.view.x,y:state.view.y}};viewport.setPointerCapture(event.pointerId);});
  viewport.addEventListener("pointermove",event=>{if(!gesture)return;if(gesture.kind==="pan"){state.view.x=gesture.origin.x+event.clientX-gesture.start.x;state.view.y=gesture.origin.y+event.clientY-gesture.start.y;applyView();return;}const p=worldPoint(event.clientX,event.clientY),item=get(gesture.id),dx=p.x-gesture.start.x,dy=p.y-gesture.start.y;if(gesture.kind==="resize"){item.w=Math.max(150,gesture.origin.w+dx);item.h=Math.max(80,gesture.origin.h+dy);}else{item.x=Math.round((gesture.origin.x+dx)/10)*10;item.y=Math.round((gesture.origin.y+dy)/10)*10;}render();});
  const finishGesture=()=>{if(gesture){const item=get(gesture.id);if(item?.type==="task"&&gesture.kind==="move")syncTask(item);save();}gesture=null;};
  viewport.addEventListener("pointerup",finishGesture);viewport.addEventListener("pointercancel",finishGesture);window.addEventListener("pointerup",finishGesture);
  viewport.addEventListener("wheel",event=>{event.preventDefault();const before=worldPoint(event.clientX,event.clientY),rect=viewport.getBoundingClientRect(),scale=Math.max(.3,Math.min(2,state.view.scale*(event.deltaY>0?.9:1.1)));state.view.scale=scale;state.view.x=event.clientX-rect.left-before.x*scale;state.view.y=event.clientY-rect.top-before.y*scale;applyView();save();},{passive:false});
  viewport.addEventListener("dblclick",event=>{if(event.target.closest(".proto-item"))return;const p=worldPoint(event.clientX,event.clientY);state.items.push({id:`note-${Date.now()}`,type:"note",x:p.x,y:p.y,w:240,h:145,title:"Новая заметка",color:"#d39b32",status:""});const note=state.items[state.items.length-1];select(note.id);save();openInspector(selected);});
  async function syncTask(item){if(!source.canEdit||!item?.sourceId)return;const statusColumns=state.items.filter(i=>i.type==="status"),sprintAreas=state.items.filter(i=>i.type==="sprint");const cx=item.x+item.w/2,cy=item.y+item.h/2,box=list=>list.find(area=>cx>=area.x&&cx<=area.x+area.w&&cy>=area.y&&cy<=area.y+area.h);const status=box(statusColumns),sprint=box(sprintAreas);const payload={};if(status&&status.status!==item.status)payload.status=status.status;if(sprint&&sprint.sourceId!==item.sprintId)payload.sprint_id=sprint.sourceId;if(!Object.keys(payload).length)return;const syncLabel=app.querySelector("[data-sync-label]");syncLabel.textContent="Синхронизация…";try{const response=await fetch(`/prototype/board/tasks/${item.sourceId}`,{method:"PATCH",headers:{"Content-Type":"application/json"},body:JSON.stringify(payload)});if(!response.ok)throw Error();const result=await response.json();item.status=result.status;item.sprintId=result.sprint_id;syncLabel.textContent="Синхронизировано";save();render();}catch(_){syncLabel.textContent="Ошибка синхронизации";}}
  function drawLinks(){linksLayer.setAttribute("viewBox","0 0 3000 2000");linksLayer.innerHTML=`<defs><marker id="proto-arrow" markerWidth="10" markerHeight="10" refX="8" refY="4" orient="auto"><path d="M0,0 L8,4 L0,8 z"/></marker></defs>`+state.links.map(link=>{const a=get(link.from),b=get(link.to);if(!a||!b)return"";const x1=a.x+a.w/2,y1=a.y+a.h/2,x2=b.x+b.w/2,y2=b.y+b.h/2;return`<path d="M${x1} ${y1} C${x1+(x2-x1)/2} ${y1},${x1+(x2-x1)/2} ${y2},${x2} ${y2}" marker-end="url(#proto-arrow)"/>`;}).join("");}
  function setTool(next){tool=next;app.querySelectorAll("[data-tool]").forEach(button=>button.classList.toggle("active",button.dataset.tool===next));viewport.classList.toggle("connect-mode",next==="connect");}
  function openInspector(id){const item=get(id),panel=app.querySelector("[data-inspector]");if(!item)return;selected=id;panel.hidden=false;panel.querySelector("[data-prop-title]").value=item.title;panel.querySelector("[data-prop-color]").value=item.color;const statusField=panel.querySelector("[data-status-field]");statusField.hidden=item.type!=="task";const select=panel.querySelector("[data-prop-status]");select.replaceChildren(...(source.statuses||[]).map(s=>{const option=document.createElement("option");option.value=s.code;option.textContent=s.label;return option;}));select.value=item.status||"";}
  function updateInspector(){const item=get(selected);if(!item)return;item.title=app.querySelector("[data-prop-title]").value;item.color=app.querySelector("[data-prop-color]").value;item.status=app.querySelector("[data-prop-status]").value;if(item.type==="task")syncTask(item);save();render();}
  function add(type){const p=worldPoint(viewport.getBoundingClientRect().left+viewport.clientWidth/2,viewport.getBoundingClientRect().top+viewport.clientHeight/2),item={id:`${type}-${Date.now()}`,type,x:p.x-100,y:p.y-60,w:type==="status"?280:type==="sprint"?320:230,h:type==="status"?500:type==="sprint"?190:type==="note"?145:105,title:type==="task"?"Новая задача":type==="status"?"Новый статус":type==="sprint"?"Новый спринт":"Новая заметка",color:type==="note"?"#d39b32":"#3276d1",status:"Backlog"};state.items.push(item);select(item.id);save();openInspector(item.id);}
  function fit(){if(!state.items.length)return;const xs=state.items.map(i=>i.x),ys=state.items.map(i=>i.y),xe=state.items.map(i=>i.x+i.w),ye=state.items.map(i=>i.y+i.h),minX=Math.min(...xs),minY=Math.min(...ys),maxX=Math.max(...xe),maxY=Math.max(...ye),scale=Math.max(.3,Math.min(1.2,Math.min((viewport.clientWidth-100)/(maxX-minX),(viewport.clientHeight-100)/(maxY-minY))));state.view.scale=scale;state.view.x=(viewport.clientWidth-(maxX-minX)*scale)/2-minX*scale;state.view.y=(viewport.clientHeight-(maxY-minY)*scale)/2-minY*scale;applyView();save();}
  function updateMinimap(){const mini=app.querySelector("[data-minimap-world]");mini.innerHTML=state.items.map(i=>`<b style="left:${i.x}px;top:${i.y}px;width:${i.w}px;height:${i.h}px"></b>`).join("");const view=app.querySelector("[data-minimap-view]");view.style.cssText=`left:${Math.max(0,-state.view.x/state.view.scale)}px;top:${Math.max(0,-state.view.y/state.view.scale)}px;width:${viewport.clientWidth/state.view.scale}px;height:${viewport.clientHeight/state.view.scale}px`;}
  app.querySelector("[data-project-select]")?.addEventListener("change",event=>{location.href=`/prototype/board?project_id=${event.target.value}`;});app.querySelectorAll("[data-add]").forEach(button=>button.addEventListener("click",()=>add(button.dataset.add)));app.querySelectorAll("[data-tool]").forEach(button=>button.addEventListener("click",()=>setTool(button.dataset.tool)));app.querySelector("[data-delete]").addEventListener("click",()=>{if(!selected)return;state.items=state.items.filter(i=>i.id!==selected);state.links=state.links.filter(l=>l.from!==selected&&l.to!==selected);selected=null;save();render();});app.querySelector("[data-zoom-in]").addEventListener("click",()=>{state.view.scale=Math.min(2,state.view.scale+.1);applyView();save();});app.querySelector("[data-zoom-out]").addEventListener("click",()=>{state.view.scale=Math.max(.3,state.view.scale-.1);applyView();save();});app.querySelector("[data-fit]").addEventListener("click",fit);["title","color","status"].forEach(key=>app.querySelector(`[data-prop-${key}]`).addEventListener("input",updateInspector));app.querySelector("[data-inspector-close]").addEventListener("click",()=>app.querySelector("[data-inspector]").hidden=true);app.querySelector("[data-reset]").addEventListener("click",()=>{localStorage.removeItem(key);location.reload();});app.querySelector("[data-export]").addEventListener("click",()=>{const link=document.createElement("a"),blob=new Blob([JSON.stringify(state,null,2)],{type:"application/json"});link.href=URL.createObjectURL(blob);link.download=`taska-canvas-${source.projectId||"board"}.json`;link.click();URL.revokeObjectURL(link.href);});app.querySelector("[data-import]").addEventListener("change",async event=>{try{const next=JSON.parse(await event.target.files[0].text());if(!Array.isArray(next.items))throw Error();state=next;save();render();applyView();}catch(_){alert("Не удалось импортировать доску");}});window.addEventListener("keydown",event=>{if((event.key==="Delete"||event.key==="Backspace")&&!event.target.matches("input,textarea"))app.querySelector("[data-delete]").click();if(event.key==="Escape"){linkStart=null;setTool("select");}});render();applyView();setTimeout(fit,50);
});
